CREATE TABLE `velix_editorial_versions` (`id` text PRIMARY KEY NOT NULL, `project_id` text NOT NULL REFERENCES `video_projects`(`id`) ON DELETE CASCADE, `idea_id` text REFERENCES `velix_production_ideas`(`id`) ON DELETE SET NULL, `kind` text NOT NULL, `version` integer NOT NULL, `content` text NOT NULL, `approved` integer NOT NULL DEFAULT 0, `created_at` text NOT NULL DEFAULT (datetime('now')));
